1	import * as THREE from 'three';
2	import { CONFIG } from '../config';
3	import { scene } from '../core/renderer';
4	import { MAT } from '../core/materials';
5	import { windFx, weatherFx, vanished, shared } from '../core/shared';
6	import { rand } from '../common/math';
7	import type { BoatTypeId } from '../config';
8	import { btCreateFleet, btSetInfo, btSetBoat, btHideBoat, btCommit, btFleets, type BoatFleet } from './boats/fleet';
9	import { btCrowdSlots, btCrowdTarget, btCrowdLevel, btCrowdShown, btInExclusion } from './boats/crowd';
10	import { TYPES, CAR_COLORS, BIKE_COLORS, placePart, _e, _q, type VehicleType } from '../common/traffic';
11	import { deckY } from '../bridges/dragon/profile';
12	import { ttlRoadY } from '../bridges/tran-thi-ly/profile';
13	
14	/* ============================ Xe cộ & thuyền của khu phố quanh Cầu Rồng ============================ */
15	interface Path { axis: 'x' | 'z'; min: number; max: number; fixed: number; profile?: (x: number) => number; hidden?: boolean }
16	interface CityVehicle { path: Path; lane: number; dir: number; type: VehicleType; s: number; speed: number; color: number }
17	
18	export const PATHS: Record<'axis' | 'ttl' | 'bachDang' | 'tranHungDao', Path> = {
19	  axis: { axis: 'x', min: -1900, max: 1480, fixed: 0, profile: deckY },
20	  ttl: { axis: 'x', min: -1900, max: 1480, fixed: CONFIG.ttl.z, profile: ttlRoadY, hidden: false }, // 2 làn trong mỗi chiều của Cầu Trần Thị Lý
21	  bachDang: { axis: 'z', min: -2400, max: 2400, fixed: -299 },
22	  tranHungDao: { axis: 'z', min: -2200, max: 2400, fixed: 299 }
23	};
24	const vehicles: CityVehicle[] = [];
25	export let vBody: THREE.InstancedMesh, vCabin: THREE.InstancedMesh, vHead: THREE.InstancedMesh, vTail: THREE.InstancedMesh;
26	
27	export function buildTraffic() {
28	  const addLane = (path: Path, lane: number, dir: number, count: number, speed: number, mix: { bike: number; bus: number }) => {
29	    const range = path.max - path.min;
30	    for (let k = 0; k < count; k++) {
31	      const r = rand(); const type: VehicleType = r < mix.bike ? 'bike' : r < mix.bike + mix.bus ? 'bus' : 'car';
32	      vehicles.push({ path, lane, dir, type, s: path.min + (k + rand() * 0.5) * range / count, speed,
33	        color: type === 'bike' ? BIKE_COLORS[k % BIKE_COLORS.length] : type === 'bus' ? 0xe8b923 : CAR_COLORS[Math.floor(rand() * CAR_COLORS.length)] });
34	    }
35	  };
36	  const lanes = [4.875, 8.625, 12.375];
37	  for (const dir of [1, -1]) {
38	    addLane(PATHS.axis, lanes[0], dir, 26, 15, { bike: 0.05, bus: 0.08 });
39	    addLane(PATHS.axis, lanes[1], dir, 30, 12.5, { bike: 0.3, bus: 0.06 });
40	    addLane(PATHS.axis, lanes[2], dir, 44, 9.5, { bike: 0.85, bus: 0 });
41	    for (const [p, n] of [[PATHS.bachDang, 26], [PATHS.tranHungDao, 22]] as [Path, number][]) {
42	      addLane(p, 3.5, dir, n, 11, { bike: 0.3, bus: 0.05 }); addLane(p, 7.5, dir, n + 10, 8.5, { bike: 0.8, bus: 0 });
43	    }
44	    addLane(PATHS.ttl, 4.625, dir, 22, 13, { bike: 0.2, bus: 0.05 }); addLane(PATHS.ttl, 8.375, dir, 30, 9, { bike: 0.8, bus: 0 });
45	  }
46	  const n = vehicles.length, box = new THREE.BoxGeometry(1, 1, 1);
47	  vBody = new THREE.InstancedMesh(box, MAT.vehicle, n);
48	  vCabin = new THREE.InstancedMesh(box, MAT.glass, n);
49	  vHead = new THREE.InstancedMesh(box, MAT.headLamp, n);
50	  vTail = new THREE.InstancedMesh(box, MAT.tailLamp, n);
51	  const col = new THREE.Color();
52	  vehicles.forEach((v, i) => { col.setHex(v.color); vBody.setColorAt(i, col); });
53	  for (const mm of [vBody, vCabin, vHead, vTail]) { mm.frustumCulled = false; mm.instanceMatrix.setUsage(THREE.DynamicDrawUsage); scene.add(mm); }
54	  vBody.castShadow = true;
55	}
56	const HIDDEN_M = new THREE.Matrix4().makeScale(0, 0, 0);
57	const _p = new THREE.Vector3();
58	const hideAt = (i: number, lamps: boolean) => { vBody.setMatrixAt(i, HIDDEN_M); vCabin.setMatrixAt(i, HIDDEN_M); if (lamps) { vHead.setMatrixAt(i, HIDDEN_M); vTail.setMatrixAt(i, HIDDEN_M); } };
59	/* Không cấp phát mỗi khung (D-018). Đèn pha/hậu chỉ hiện khi đêm > 0,3 (applyNight đặt visible trước hàm này): khi ẩn không ghi ma trận đèn;
60	   vị trí xe (v.s) vẫn cộng dồn như cũ nên khung đèn hiện lại thì ma trận được ghi đúng chỗ ngay trong khung đó */
61	export function updateTraffic(dt: number) {
62	  const lamps = vHead.visible;
63	  for (let i = 0; i < vehicles.length; i++) {
64	    const v = vehicles[i], P = v.path, range = P.max - P.min, T = TYPES[v.type];
65	    if (P.hidden) { hideAt(i, lamps); continue; } // làn tắt bằng nút bật/tắt
66	    v.s += v.dir * v.speed * dt;
67	    if (v.s > P.max) v.s -= range; if (v.s < P.min) v.s += range;
68	    if ((P === PATHS.axis || P === PATHS.ttl) && vanished(i, weatherFx.clear)) { hideAt(i, lamps); continue; }   // đóng cầu (bão): dọn dần xe trên Cầu Rồng, Trần Thị Lý
69	    let yaw: number, pitch = 0;
70	    if (P.axis === 'x') {
71	      const y = P.profile(v.s), slope = (P.profile(v.s + 1) - P.profile(v.s - 1)) / 2;
72	      _p.set(v.s, y + 0.02, P.fixed + v.dir * v.lane); yaw = v.dir > 0 ? 0 : Math.PI; pitch = Math.atan(slope * v.dir);
73	    } else {
74	      _p.set(P.fixed - v.dir * v.lane, CONFIG.roadY + 0.03, v.s); yaw = v.dir > 0 ? -Math.PI / 2 : Math.PI / 2;
75	    }
76	    _q.setFromEuler(_e.set(0, yaw, pitch, 'YZX'));
77	    placePart(vBody, i, _p, _q, 0, 0.3 + T.h / 2, T.len, T.h, T.w);
78	    placePart(vCabin, i, _p, _q, T.co * T.len, 0.3 + T.h + T.ch / 2, T.cl, T.ch, T.cw);
79	    if (!lamps) continue;
80	    placePart(vHead, i, _p, _q, T.len / 2 + 0.04, 0.3 + T.h * 0.6, 0.1, 0.22, T.w * 0.8);
81	    placePart(vTail, i, _p, _q, -T.len / 2 - 0.04, 0.3 + T.h * 0.6, 0.1, 0.22, T.w * 0.8);
82	  }
83	  vBody.instanceMatrix.needsUpdate = vCabin.instanceMatrix.needsUpdate = true;
84	  if (lamps) vHead.instanceMatrix.needsUpdate = vTail.instanceMatrix.needsUpdate = true;
85	}
86	
87	/* Vùng cấm thuyền quanh công trường dìm đốt hầm (Hầm vượt sông Hàn, z ≈ −1700): chỉ có hiệu lực khi on */
88	export const boatKeepOut = { on: false, z0: -1760, z1: -1640 };
89	
90	/* Thuyền du lịch dọc sông Hàn — một đội tàu (fleet) chung ở layer 0 (có phản chiếu): 7 tàu chạy + chỗ cho 15 tàu tụ tập ban đêm (Task 4) */
91	export interface RiverBoat { x: number; z: number; dir: number; speed: number; len: number; type: BoatTypeId }
92	const boats: RiverBoat[] = [];
93	let fleet: BoatFleet;
94	export const RIVER_CROWD_FIRST = 7;   // instance 7.. dành cho tàu tụ tập
95	export function buildBoats() {
96	  const lanesX = [-48, -22, 22, 48];
97	  for (let i = 0; i < 7; i++) {
98	    // giữ đúng 2 lời gọi rand() mỗi tàu, đúng thứ tự (speed rồi len) — bất biến chuỗi seed; r đổi sang khoảng dài của kiểu
99	    const speed = 3 + rand() * 2, r = rand(), type: BoatTypeId = i % 2 ? 'B' : 'A', [lo, hi] = CONFIG.boats.types[type].len;
100	    boats.push({ x: lanesX[i % 4], z: -2200 + i * 650, dir: lanesX[i % 4] > 0 ? 1 : -1, speed, len: lo + r * (hi - lo), type });
101	  }
102	  fleet = btCreateFleet(RIVER_CROWD_FIRST + crowd.length, ['A', 'B', 'C'], scene, 'boats-river');
103	  boats.forEach((b, i) => btSetInfo(fleet, i, { type: b.type, variant: i % 3, led: (i * 2) % CONFIG.boats.led.colors.length, name: i % CONFIG.boats.names.length }));
104	  crowd.forEach((c, k) => btSetInfo(fleet, RIVER_CROWD_FIRST + k, c));
105	}
106	/* Tàu tụ tập ban đêm quanh Cầu Rồng / Cầu sông Hàn (spec G5, G6): đậu, trôi tròn chậm, mũi lắc nhẹ; hiện so le theo mức đêm, về bến khi bão */
107	const crowd = btCrowdSlots(), crowdA: number[] = crowd.map(() => 0);
108	let crowdLevel = 0;
109	export function btStepCrowd(f: BoatFleet, first: number, t: number, dt: number) {
