87	/* Vùng cấm thuyền quanh công trường dìm đốt hầm (Hầm vượt sông Hàn, z ≈ −1700): chỉ có hiệu lực khi on */
88	export const boatKeepOut = { on: false, z0: -1760, z1: -1640 };
89	
90	/* Thuyền du lịch dọc sông Hàn — một đội tàu (fleet) chung ở layer 0 (có phản chiếu): 7 tàu chạy + chỗ cho 15 tàu tụ tập ban đêm (Task 4) */
91	export interface RiverBoat { x: number; z: number; dir: number; speed: number; len: number; type: BoatTypeId }
92	const boats: RiverBoat[] = [];
93	let fleet: BoatFleet;
94	export const RIVER_CROWD_FIRST = 7;   // instance 7.. dành cho tàu tụ tập
95	export function buildBoats() {
96	  const lanesX = [-48, -22, 22, 48];
97	  for (let i = 0; i < 7; i++) {
98	    // giữ đúng 2 lời gọi rand() mỗi tàu, đúng thứ tự (speed rồi len) — bất biến chuỗi seed; r đổi sang khoảng dài của kiểu
99	    const speed = 3 + rand() * 2, r = rand(), type: BoatTypeId = i % 2 ? 'B' : 'A', [lo, hi] = CONFIG.boats.types[type].len;
100	    boats.push({ x: lanesX[i % 4], z: -2200 + i * 650, dir: lanesX[i % 4] > 0 ? 1 : -1, speed, len: lo + r * (hi - lo), type });
101	  }
102	  fleet = btCreateFleet(RIVER_CROWD_FIRST + crowd.length, ['A', 'B', 'C'], scene, 'boats-river');
103	  boats.forEach((b, i) => btSetInfo(fleet, i, { type: b.type, variant: i % 3, led: (i * 2) % CONFIG.boats.led.colors.length, name: i % CONFIG.boats.names.length }));
104	  crowd.forEach((c, k) => btSetInfo(fleet, RIVER_CROWD_FIRST + k, c));
105	}
106	/* Tàu tụ tập ban đêm quanh Cầu Rồng / Cầu sông Hàn (spec G5, G6): đậu, trôi tròn chậm, mũi lắc nhẹ; hiện so le theo mức đêm, về bến khi bão */
107	const crowd = btCrowdSlots(), crowdA: number[] = crowd.map(() => 0);
108	let crowdLevel = 0;
109	export function btStepCrowd(f: BoatFleet, first: number, t: number, dt: number) {
110	  const C = CONFIG.boats.crowd, w = (Math.PI * 2) / C.driftPeriod;
111	  crowdLevel = btCrowdLevel(crowdLevel, btCrowdTarget(shared.uNight.value, weatherFx.boatAway), dt);
112	  crowd.forEach((c, k) => {
113	    const on = btCrowdShown(k, crowdLevel); crowdA[k] = on ? 1 : 0;
114	    if (!on) { btHideBoat(f, first + k); return; }
115	    const ph = t * w + c.phase, i = first + k;
116	    bq.setFromEuler(_e.set(Math.sin(t * 0.7 + k) * 0.012 * windFx.boatRock, c.yaw + C.yawSwing * Math.sin(ph * 0.7), Math.sin(t * 0.9 + k * 2) * 0.018 * windFx.boatRock, 'YXZ'));
117	    btSetBoat(f, i, bBase.set(c.x + C.drift * Math.cos(ph), 0, c.z + C.drift * Math.sin(ph)), bq, c.len);
118	  });
119	}
120	const bq = new THREE.Quaternion(), bBase = new THREE.Vector3();
121	export function updateBoats(dt: number, t: number) {
122	  boats.forEach((b, i) => {
123	    b.z += b.dir * b.speed * dt * (1 - weatherFx.boatAway); if (b.z > 2500) b.z = -2500; if (b.z < -2500) b.z = 2500;   // bão: thuyền chậm dần rồi dừng
124	    if (boatKeepOut.on && b.z > boatKeepOut.z0 && b.z < boatKeepOut.z1) b.z = b.dir > 0 ? boatKeepOut.z0 : boatKeepOut.z1;
125	    if (vanished(i, weatherFx.boatAway)) { btHideBoat(fleet, i); return; }   // về bến: ẩn dần
126	    bq.setFromEuler(_e.set(Math.sin(t * 0.9 + i) * 0.015 * windFx.boatRock, b.dir > 0 ? 0 : Math.PI, Math.sin(t * 1.1 + i * 2) * 0.02 * windFx.boatRock, 'YXZ'));   // mũi theo hướng chạy; tròng trành tăng theo gió (mặc định ×1)
127	    btSetBoat(fleet, i, bBase.set(b.x, 0, b.z), bq, b.len);
128	  });
129	  btStepCrowd(fleet, RIVER_CROWD_FIRST, t, dt);
130	  btCommit(fleet);
131	}
132	/* Cho test (__app.boats) */
133	export const boatsTest = { fleets: () => btFleets, running: () => boats, types: CONFIG.boats.types, crowd, crowdFirst: RIVER_CROWD_FIRST, crowdAlpha: () => crowdA, inExclusion: btInExclusion, drift: CONFIG.boats.crowd.drift };
