1	import * as THREE from 'three';
2	import { renderer, scene } from '../../core/renderer';
3	import { MAT } from '../../core/materials';
4	import { canvasTex } from '../../core/textures';
5	import { water } from '../../core/water';
6	import { CONFIG } from '../../config';
7	import { HR, HR_HOLES, hrRoadY, hrBedY, hrTrenchY } from './profile';
8	import type { HrMaterials } from './materials';
9	import { btFleetMaterial } from '../../environment/boats/material';
10	
11	/* [cutaway] Hai chế độ xem dưới lòng đất:
12	   • Mặt cắt địa chất (section): bóc dải đất phía Bắc mặt cắt dọc tim ống Nam, hiện tấm địa chất, nước trong suốt.
13	     Bóc bằng clippingPlanes + clipIntersection (4 mặt phẳng ⇒ một hình hộp bị loại bỏ), riêng nước dùng discard trong shader.
14	   • Nước trong (glass): chỉ làm nước trong suốt để thấy hào nạo vét và đốt hầm đang dìm (dùng khi mô phỏng dìm đốt hầm).
15	   Mặt phẳng cắt gán cố định từ khi dựng (D-018): đổi clippingPlanes/clipIntersection làm mọi vật liệu biên dịch lại shader (~45 vật liệu + nhà,
16	   giật vài giây). Tắt = đẩy mặt phẳng đầu ra rất xa: với clipIntersection, điểm chỉ bị cắt khi nằm phía âm của CẢ 4 mặt phẳng ⇒ không điểm nào bị cắt. */
17	export const CUT_X = HR.approachHalf + 40;     // m — nửa chiều dài vùng bóc
18	export const CUT_Z = HR.z + HR.cutZ;           // m — mặt cắt (thế giới), qua tim ống Nam
19	export const CUT_STRIP = 110;                  // m — bề rộng dải bị bóc, phía Bắc mặt cắt
20	const Y_TOP = 8, Y_BOT = -45;
21	const PLANE_OFF = 1e7;                         // m — hằng số mặt phẳng đầu khi tắt mặt cắt: mọi điểm nằm phía dương ⇒ không cắt
22	
23	/* Nhãn 3D trên mặt cắt: khóa i18n + tọa độ thế giới */
24	export const CUT_LABELS: { key: string; pos: [number, number, number] }[] = [
25	  { key: 'hrLblElements', pos: [-150, -13, CUT_Z] },
26	  { key: 'hrLblGina', pos: [60, -10, CUT_Z] },
27	  { key: 'hrLblBed', pos: [150, -4.6, CUT_Z] },
28	  { key: 'hrLblPump', pos: [-9, -12, HR.z + HR.tubeFar - 0.7] },
29	  { key: 'hrLblCover', pos: [400, -4, CUT_Z] },
30	  { key: 'hrLblRamp', pos: [600, 1.5, CUT_Z] },
31	  { key: 'hrLblFlood', pos: [HR.rampHalf + 7, 4.4, CUT_Z] }
32	];
33	
34	const LAYERS: [number, string, string][] = [[-2, '#d8c58f', 'cát san lấp'], [-9, '#c3a869', 'cát pha'], [-22, '#7f8f72', 'sét yếu'], [-34, '#8d7058', 'sét cứng'], [Y_BOT, '#6b6865', 'đá phong hoá']];
35	
36	function drawGeology() {
37	  const W = 4096, H = Math.round((Y_TOP - Y_BOT) * 12), kx = W / (2 * CUT_X), ky = 12;
38	  const px = (x: number) => (CUT_X - x) * kx, py = (y: number) => (Y_TOP - y) * ky;   // đông ở bên trái khi nhìn từ phía Bắc
39	  return canvasTex(W, H, (g) => {
40	    const surf = (x: number) => (Math.abs(x) <= 264 ? hrBedY(x) : CONFIG.landY);
41	    // các lớp đất, mỗi cột 1 px
42	    for (let c = 0; c < W; c++) {
43	      const x = CUT_X - (c + 0.5) / kx, s = surf(x);
44	      let top = s;
45	      for (const [bot, col] of LAYERS) {
46	        if (top <= bot) continue;
47	        g.fillStyle = col; g.fillRect(c, py(top), 1.2, py(bot) - py(top) + 1); top = bot;
48	      }
49	      if (Math.abs(x) <= 264) { g.fillStyle = 'rgba(70,150,185,0.55)'; g.fillRect(c, py(0), 1.2, py(s) - py(0)); }   // cột nước sông
50	    }
51	    // lớp đá hộc trong hào nạo vét
52	    g.fillStyle = '#8b8880';
53	    for (let c = 0; c < W; c++) { const x = CUT_X - (c + 0.5) / kx; if (Math.abs(x) <= 264) g.fillRect(c, py(hrBedY(x)), 1.2, py(hrTrenchY(x)) - py(hrBedY(x))); }
54	    // vỏ hầm: bản nóc và bản đáy (cắt qua), ống rỗng
55	    for (let c = 0; c < W; c++) {
56	      const x = CUT_X - (c + 0.5) / kx, a = Math.abs(x), R = hrRoadY(x);
57	      if (a <= HR.coverHalf) {
58	        g.fillStyle = '#b6b3ab'; g.fillRect(c, py(R + HR.roofTop), 1.2, py(R + HR.clear) - py(R + HR.roofTop) + 1);
59	        g.fillRect(c, py(R), 1.2, py(R - HR.slabBelow) - py(R) + 1);
60	      } else if (a <= HR.rampHalf) {
61	        g.clearRect(c, 0, 1.2, py(R));                                               // máng hầm hở: bỏ đất phía trên sàn
62	        g.fillStyle = '#b6b3ab'; g.fillRect(c, py(R), 1.2, py(R - HR.slabBelow) - py(R) + 1);
63	      }
64	    }
65	    g.globalCompositeOperation = 'destination-out';                                  // lòng ống xe: để trống cho thấy nội thất 3D
66	    for (let c = 0; c < W; c++) { const x = CUT_X - (c + 0.5) / kx; if (Math.abs(x) <= HR.coverHalf) { const R = hrRoadY(x); g.fillRect(c, py(R + HR.clear), 1.2, py(R) - py(R + HR.clear)); } }
67	    g.globalCompositeOperation = 'source-over';
68	    // đường mặt đất, mực nước, lưới cao độ
69	    g.strokeStyle = 'rgba(30,30,30,0.7)'; g.lineWidth = 2; g.beginPath();
70	    for (let c = 0; c < W; c += 2) { const x = CUT_X - c / kx, y = Math.abs(x) <= 264 ? hrBedY(x) : CONFIG.landY; c ? g.lineTo(c, py(y)) : g.moveTo(c, py(y)); }
71	    g.stroke();
72	    g.strokeStyle = 'rgba(255,255,255,0.28)'; g.fillStyle = 'rgba(255,255,255,0.8)'; g.lineWidth = 1; g.font = '14px "JetBrains Mono", monospace';
73	    for (let y = 0; y >= Y_BOT; y -= 10) { g.beginPath(); g.moveTo(0, py(y)); g.lineTo(W, py(y)); g.stroke(); g.fillText(`${y} m`, 8, py(y) - 3); g.fillText(`${y} m`, W - 56, py(y) - 3); }
74	    g.setLineDash([10, 8]); g.strokeStyle = 'rgba(80,170,255,0.9)'; g.beginPath(); g.moveTo(px(CUT_X), py(0.4)); g.lineTo(px(264), py(0.4)); g.moveTo(px(-264), py(0.4)); g.lineTo(px(-CUT_X), py(0.4)); g.stroke();   // mực nước ngầm
75	  });
76	}
77	/* Dải cột chữ cái cho tên lớp đất (ghi bên trái bảng) */
78	export class Cutaway {
79	  section = false; glass = false;
80	  readonly planes: THREE.Plane[];
81	  readonly plane: THREE.Mesh;
82	  private mats: THREE.Material[] = [];
83	
84	  constructor(M: HrMaterials) {
85	    renderer.localClippingEnabled = true;
86	    // vùng bị bóc: x ∈ (−CUT_X, CUT_X), z ∈ (CUT_Z − CUT_STRIP, CUT_Z) — clipIntersection nên chỉ phần nằm ngoài CẢ 4 mặt phẳng mới bị cắt
87	    this.planes = [
88	      new THREE.Plane(new THREE.Vector3(-1, 0, 0), PLANE_OFF), new THREE.Plane(new THREE.Vector3(1, 0, 0), -CUT_X),
89	      new THREE.Plane(new THREE.Vector3(0, 0, -1), CUT_Z - CUT_STRIP), new THREE.Plane(new THREE.Vector3(0, 0, 1), -CUT_Z)
90	    ];
91	    // tấm mặt cắt địa chất đặt sát mặt phía Nam, quay mặt về phía Bắc (nơi camera đứng)
92	    const tex = drawGeology(); M.textures.push(tex);
93	    this.plane = new THREE.Mesh(new THREE.PlaneGeometry(CUT_X * 2, Y_TOP - Y_BOT), new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.04, fog: false }));
94	    this.plane.rotation.y = Math.PI; this.plane.position.set(0, (Y_TOP + Y_BOT) / 2, CUT_Z + 0.04);
95	    this.plane.visible = false; this.plane.name = 'hr-geology'; this.plane.layers.set(1); scene.add(this.plane);
96	    this.patchWater();
97	    // vật liệu bị bóc: đất, đường, cây, đèn, nhà (vật liệu riêng của buildCity) và hầm
98	    const set = new Set<THREE.Material>([MAT.land, MAT.sand, MAT.paver, MAT.stone, MAT.grass, MAT.road, MAT.road2, MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb,
99	      MAT.vehicle, MAT.glass, MAT.headLamp, MAT.tailLamp, btFleetMaterial,
100	      M.concrete, M.bore, M.roadIn, M.roadOut, M.louver, M.brick, M.wave, M.bed, M.rubble, M.steel, M.lampThr, M.lampIn, M.lampCorr, M.fan, M.sos, M.extinguisher, M.door, M.exit, M.laneGreen, M.guide, M.equip, M.grate, M.basket]);
101	    scene.traverse((o) => { const i = o as THREE.InstancedMesh; if (i.isInstancedMesh && i.parent && (i.parent as THREE.LOD).isLOD) set.add(i.material as THREE.Material); });
102	    this.mats = [...set];
103	    for (const m of this.mats) { m.clippingPlanes = this.planes; m.clipIntersection = true; m.needsUpdate = true; }   // lúc dựng, trước lần biên dịch đầu
104	  }
105	  /* Nước: bỏ các điểm nằm trong máng hầm hở (nước trải vô hạn ở y = 0 sẽ lọt vào máng) và trong vùng bóc khi bật mặt cắt */
106	  private patchWater() {
107	    const mat = water.material as THREE.ShaderMaterial;
