34	import * as THREE from 'three';
35	import { OrbitControls } from '/files/OrbitControls.js';
36	
37	const renderer = new THREE.WebGLRenderer({ antialias: true });
38	renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
