49	/* ---------- vật liệu ---------- */
50	const std = (color, o = {}) => new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.08, flatShading: true, side: THREE.DoubleSide, ...o });
51	const M = {
52	  glass: std(0x10161d, { roughness: 0.12, metalness: 0.8 }),
53	  tyre: std(0x15171a, { roughness: 0.9, metalness: 0 }),
54	  rim: std(0x9aa0a8, { roughness: 0.3, metalness: 0.8 }),
