63	/* ---------- dựng hình: vỏ lượn theo các mặt cắt dọc xe ---------- */
64	function loft(st, mat) {
65	  const pos = [];
66	  const ring = (s) => { const t = s.t ?? 0.8; return [[-s.w, s.y0], [-s.w, s.ym], [-s.w * t, s.y1], [s.w * t, s.y1], [s.w, s.ym], [s.w, s.y0]].map(([z, y]) => [s.x, y, z]); };
67	  const R = st.map(ring), tri = (a, b, c) => pos.push(...a, ...b, ...c);
68	  for (let i = 0; i < R.length - 1; i++) for (let j = 0; j < 6; j++) { const k = (j + 1) % 6; tri(R[i][j], R[i + 1][j], R[i + 1][k]); tri(R[i][j], R[i + 1][k], R[i][k]); }
69	  for (const r of [R[0], R[R.length - 1]]) for (let j = 1; j < 5; j++) tri(r[0], r[j], r[j + 1]);
70	  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.computeVertexNormals();
71	  return new THREE.Mesh(g, mat);
72	}
73	const box = (mat, sx, sy, sz, x, y, z = 0, rz = 0) => { const m = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), mat); m.position.set(x, y, z); m.rotation.z = rz; return m; };
74	function wheel(r, w, x, z) {
