160	const TYPES = { car: { len: 4.4, h: 0.8, w: 1.8, cl: 2.3, ch: 0.62, cw: 1.6, co: -0.25 }, bus: { len: 11, h: 2.6, w: 2.5, cl: 10.4, ch: 0.25, cw: 2.3, co: 0 }, bike: { len: 1.9, h: 0.65, w: 0.6, cl: 0.55, ch: 1.0, cw: 0.45, co: -0.2 } };
161	function oldBox(type, color) {
