12	/* [life] xe dừng trước barie, người đi bộ, thuyền du lịch, tàu buồm cao chờ mở luồng */
13	export function shBuildLife(bridge: SongHanBridge) {
14	  bridge.traffic = createTraffic(bridge, { seed: 2000, x0: -1500, x1: 1480, busColor: 0x2f7fc1,
15	    lanes: [{ off: SH.lane, n: 26, speed: 11, bike: 0.6, bus: 0.04 }] });
16	  // thuyền du lịch nối lộ trình Cầu Rồng – Cầu sông Hàn – Cầu Thuận Phước (giữa các làn thuyền chung)
17	  bridge.boats = createBoats(bridge, [
18	    { x: 31, z: 700, dir: -1, speed: 3.4, len: 22, w: 7, h: 2.6, cab: 2.9, type: 'A' },
19	    { x: 41, z: -900, dir: 1, speed: 3.0, len: 18, w: 6.5, h: 2.5, cab: 2.7, type: 'B' }
20	  ], 'sh-boats');
21	  // người đi bộ: lề cầu (phần cố định) và lề ven sông Bạch Đằng
22	  const rnd = rng(2903), list: Walker[] = [], zs = SH.hw - SH.sidewalk / 2 - 0.15;
23	  for (let i = 0; i < 36; i++) {
24	    const west = i % 2 === 0, lo = west ? -285 : SH.fixedStart + 8, hi = west ? -SH.fixedStart - 8 : 285;
25	    list.push({ x: lerp(lo, hi, rnd()), z: (rnd() < 0.5 ? -1 : 1) * zs, lo, hi, dir: rnd() < 0.5 ? -1 : 1, speed: 1 + rnd() * 0.5, profile: (x) => shRoadY(x) + 0.25 });
26	  }
27	  for (let i = 0; i < 40; i++) list.push({ x: -276 + (rnd() - 0.5) * 18, z: lerp(-420, 420, rnd()), lo: -420, hi: 420, dir: rnd() < 0.5 ? -1 : 1,
28	    speed: 0.9 + rnd() * 0.5, axis: 'z', profile: () => CONFIG.landY + 0.05 });
29	  bridge.people = createPeople(bridge, list, bridge.mats.person, 'sh-people', rnd);
30	  // tàu buồm cao: cột buồm cao hơn tĩnh không, chỉ qua được khi cầu mở (luồng phía Tây)
31	  const ship = new THREE.Group(); ship.name = 'sh-tall-ship';
32	  // một đội tàu 1 chiếc kiểu E (thân, nhà boong, cột, buồm gộp) = 1 lệnh vẽ; group ship vẫn do SongHanBridge di chuyển
33	  const tall = btCreateFleet(1, ['E'], ship, 'sh-tall-ship-boat');
