41	/* Xe: như hệ chung, nhưng khi không cho vào nhịp quay thì xếp hàng trước barie */
42	const before: BridgeVehicle[] = [];          // mảng tạm dùng lại (D-018)
43	let saved = new Float64Array(0);           // tốc độ gốc (double: trả lại đúng từng bit)
44	const byDist = (a: BridgeVehicle, b: BridgeVehicle) => Math.abs(a.s) - Math.abs(b.s);
45	export function shStepTraffic(T: Traffic, dt: number, ctrl: SwingController) {
46	  const bx = SH.barrierX;
47	  if (!ctrl.allowEntry) {
48	    for (const dir of [1, -1]) {
49	      before.length = 0;
50	      for (const v of T.list) if (v.dir === dir && (dir > 0 ? v.s < -bx : v.s > bx)) before.push(v);
51	      before.sort(byDist);
52	      before.forEach((v, r) => { v.hold = bx + 3 + r * 7.5; });
53	    }
54	  }
55	  if (saved.length !== T.list.length) saved = new Float64Array(T.list.length);
56	  for (let i = 0; i < T.list.length; i++) saved[i] = T.list[i].speed;
57	  T.list.forEach((v) => {
58	    if (ctrl.allowEntry || v.hold === undefined) return;
59	    const stopAt = -v.dir * v.hold, dist = (stopAt - v.s) * v.dir;          // khoảng còn lại tới vị trí dừng
60	    if (dist <= 0 || (v.dir > 0 ? v.s >= -bx : v.s <= bx)) return;          // đã qua barie thì chạy tiếp
61	    v.speed = Math.min(v.speed, Math.max(0, dist / Math.max(dt, 1e-3)));
62	  });
63	  stepTraffic(T, dt, shRoadY);
64	  T.list.forEach((v, i) => { v.speed = saved[i]; if (ctrl.allowEntry) delete v.hold; });
65	}
