8	   VẬT LIỆU ĐỘI TÀU — một vật liệu cho mọi tàu (D-026).
9	   - aPart (theo đỉnh) ≠ aBoat.x (theo instance) ⇒ thu đỉnh về gốc: tam giác suy biến, không rasterize ⇒ một InstancedMesh vẽ nhiều kiểu.
10	   - aBoat = (kiểu, biến thể màu sọc, màu LED, tên); aGlow (theo đỉnh) = loại đèn (hulls.ts → Glow).
11	   - Đèn đêm bằng emissive nhân uNight; không đèn thật.
12	   Bóng đổ dùng btDepthMaterial cùng bản vá, nếu không lượt vẽ bóng sẽ vẽ chồng mọi kiểu.
13	   ===================================================================== */
14	const B = CONFIG.boats;
15	const STRIPES = B.palette.stripes;   // màu sọc thân theo biến thể (config.ts)
16	
17	const VS_HEAD = /* glsl */`
18	attribute float aPart;
19	attribute float aGlow;
20	attribute vec4 aBoat;
21	varying float vGlow;
22	varying vec4 vBoat;
23	`;
24	const VS_COLLAPSE = /* glsl */`#include <begin_vertex>
25	if ( abs( aPart - aBoat.x ) > 0.5 ) transformed = vec3( 0.0 );`;
26	
27	const uniforms = {
28	  uNight: shared.uNight,
29	  uStripe: { value: STRIPES.map((c) => new THREE.Color(c)) },
30	  uWin: { value: new THREE.Color(B.windowColor).multiplyScalar(B.windowGain) },
31	  uLed: { value: B.led.colors.map((c) => new THREE.Color(c).multiplyScalar(B.led.gain)) },
32	  uNavR: { value: new THREE.Color(B.palette.navRed).multiplyScalar(B.palette.navGain) },
33	  uNavG: { value: new THREE.Color(B.palette.navGreen).multiplyScalar(B.palette.navGain) }
34	};
35	
36	export const btFleetMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.55, metalness: 0.05, map: btNameAtlas() });
37	btFleetMaterial.name = 'boatFleet';
38	btFleetMaterial.onBeforeCompile = (s) => {
39	  Object.assign(s.uniforms, uniforms);
40	  s.vertexShader = VS_HEAD + s.vertexShader
41	    .replace('#include <begin_vertex>', VS_COLLAPSE)
42	    .replace('#include <uv_vertex>', `#include <uv_vertex>
43	vGlow = aGlow; vBoat = aBoat;
44	if ( aGlow > 4.5 && aGlow < 5.5 ) vMapUv.y += aBoat.w / ${ATLAS_ROWS.toFixed(1)};   // biển tên: dịch tới hàng tên của tàu`);
45	  s.fragmentShader = /* glsl */`
46	uniform float uNight;
47	uniform vec3 uStripe[ ${STRIPES.length} ];
48	uniform vec3 uWin;
49	uniform vec3 uLed[ ${B.led.colors.length} ];
50	uniform vec3 uNavR;
51	uniform vec3 uNavG;
52	varying float vGlow;
53	varying vec4 vBoat;
54	` + s.fragmentShader
55	    .replace('#include <color_fragment>', `#include <color_fragment>
56	if ( vGlow > 6.5 ) diffuseColor.rgb = uStripe[ int( clamp( vBoat.y, 0.0, ${(STRIPES.length - 1).toFixed(1)} ) ) ];   // sọc thân theo biến thể`)
57	    .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
58	// đèn đêm đứng yên (không nhấp nháy): chỉ nhân uNight
59	if ( vGlow > 0.5 && vGlow < 1.5 ) totalEmissiveRadiance += uWin * uNight;                                                      // cửa sổ cabin vàng ấm
60	else if ( vGlow > 1.5 && vGlow < 2.5 ) totalEmissiveRadiance += uLed[ int( clamp( vBoat.z, 0.0, ${(B.led.colors.length - 1).toFixed(1)} ) ) ] * uNight;   // viền LED theo màu của tàu
61	else if ( vGlow > 2.5 && vGlow < 3.5 ) totalEmissiveRadiance += uNavR * uNight;                             // đèn mạn đỏ
62	else if ( vGlow > 3.5 && vGlow < 4.5 ) totalEmissiveRadiance += uNavG * uNight;                             // đèn mạn xanh
63	else if ( vGlow > 4.5 && vGlow < 5.5 ) totalEmissiveRadiance += diffuseColor.rgb * 1.4 * uNight;                              // biển tên sáng
64	else if ( vGlow > 5.5 && vGlow < 6.5 ) totalEmissiveRadiance += vColor * 2.0 * uNight;                                        // đèn lồng`);
65	  btFleetMaterial.userData.fs = s.fragmentShader;
66	  btFleetMaterial.userData.vs = s.vertexShader;
67	};
68	btFleetMaterial.customProgramCacheKey = () => 'boatFleet';
69	
70	export const btDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
71	btDepthMaterial.onBeforeCompile = (s) => {
72	  s.vertexShader = 'attribute float aPart;\nattribute vec4 aBoat;\n' + s.vertexShader.replace('#include <begin_vertex>', VS_COLLAPSE);
73	  btDepthMaterial.userData.vs = s.vertexShader;
74	};
75	btDepthMaterial.customProgramCacheKey = () => 'boatDepth';
