1	import * as THREE from 'three';
2	import type { BoatTypeId } from '../../config';
3	import { btBuildFleetGeometry, BOAT_TYPES } from './hulls';
4	import { btFleetMaterial, btDepthMaterial } from './material';
5	
6	/* =====================================================================
7	   ĐỘI TÀU (fleet) — một InstancedMesh cho mỗi nhóm tàu = 1 lệnh vẽ (thay 3 khối hộp thân / cabin / mái).
8	   Hình học gộp các kiểu nhóm cần; aBoat (instance) chọn kiểu, biến thể, màu LED, tên.
9	   ===================================================================== */
10	export interface BoatInfo { type: BoatTypeId; variant: number; led: number; name: number }
11	export interface BoatFleet { mesh: THREE.InstancedMesh; types: BoatTypeId[]; info: THREE.InstancedBufferAttribute }
12	
13	export const btFleets: BoatFleet[] = [];   // để test (__app.boats.fleets)
14	const HIDDEN = new THREE.Matrix4().makeScale(0, 0, 0);
15	
16	export function btCreateFleet(capacity: number, types: BoatTypeId[], parent: THREE.Object3D, name: string): BoatFleet {
17	  const geo = btBuildFleetGeometry(types), info = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
18	  geo.setAttribute('aBoat', info);
19	  const mesh = new THREE.InstancedMesh(geo, btFleetMaterial, capacity);
20	  mesh.name = name; mesh.customDepthMaterial = btDepthMaterial; mesh.frustumCulled = false; mesh.castShadow = true;
21	  for (let i = 0; i < capacity; i++) mesh.setMatrixAt(i, HIDDEN);
22	  parent.add(mesh);
23	  const f = { mesh, types, info }; btFleets.push(f);
24	  return f;
25	}
26	/* Gán kiểu / biến thể / LED / tên — chỉ gọi lúc dựng */
27	export function btSetInfo(f: BoatFleet, i: number, b: BoatInfo) {
28	  f.info.setXYZW(i, BOAT_TYPES.indexOf(b.type), b.variant, b.led, b.name); f.info.needsUpdate = true;
29	}
30	const _m = new THREE.Matrix4(), _s = new THREE.Vector3();
31	/* Đặt tàu i: base = điểm mặt nước dưới tâm tàu, q = hướng + tròng trành, len = chiều dài (m; hình học dài 1) */
32	export function btSetBoat(f: BoatFleet, i: number, base: THREE.Vector3, q: THREE.Quaternion, len: number) {
33	  f.mesh.setMatrixAt(i, _m.compose(base, q, _s.setScalar(len)));
34	}
35	export function btHideBoat(f: BoatFleet, i: number) { f.mesh.setMatrixAt(i, HIDDEN); }
36	export function btCommit(f: BoatFleet) { f.mesh.instanceMatrix.needsUpdate = true; }
